mapper.select:

SELECT A.GICHO_NO AS POST_NO,
       A.SIDO_NM || ' ' || A.SIGUNGU_NM || ' ' || A.BUBJUNG_NM || ' ' ||
       A.BUBJUNGRI_NM || ' ' || A.JIBUNB_NO ||
       DECODE(A.JIBUNS_NO, NULL, '', '-' || A.JIBUNS_NO) || ' ' ||
       A.SIGUNGUB_NM AS JIBUN_AD
  FROM V_POST_JIBUN A
 WHERE A.ROAD_CD = #{ROAD_CD}
   AND A.JIHA_YN = #{JIHA_YN}
   AND A.BUILDB_NO = #{BUILDB_NO}
   AND A.BUILDS_NO = #{BUILDS_NO}

SELECT DISTINCT POST_NO, ROAD_AD, BUBJUNG_CD, BUBJUNG_NM, HJD_CD, HJD_NM, ROAD_CD, EMD_SN, JIHA_YN, BUILDB_NO, BUILDS_NO, ROAD_AD || '[번지 : ' || JIBUNB_NO || '-' || JIBUNS_NO || ']' AS ZDISPLAY_AD, SIGUNGUB_NM, JIBUN_AD, JIBUNB_NO, JIBUNS_NO FROM (
/* 도로명 검색 */ SELECT A.GICHO_NO AS POST_NO, A.SIDO_NM || ' ' || A.SIGUNGU_NM || DECODE(B.EMD_GB, '0', ' ' || A.BUBJUNG_NM, '') || ' ' || A.ROAD_NM || DECODE(A.JIHA_YN, '0', '', '1', '지하', '2', '공중') || ' ' || A.BUILDB_NO || DECODE(A.BUILDS_NO, 0, ' ', '-' || A.BUILDS_NO || ' ' || A.SIGUNGUB_NM) || ' ' || CASE WHEN B.EMD_GB = '0' AND A.COMMB_YN = '0' THEN '' WHEN B.EMD_GB = '0' AND A.COMMB_YN = '1' THEN '(' || A.SIGUNGUB_NM || ')' WHEN B.EMD_GB = '1' AND A.COMMB_YN = '0' THEN '(' || A.BUBJUNG_NM || ')' WHEN B.EMD_GB = '1' AND A.COMMB_YN = '1' THEN '(' || A.BUBJUNG_NM || DECODE(A.SIGUNGUB_NM, NULL, '', ',' || A.SIGUNGUB_NM) || ')' END AS ROAD_AD, A.BUBJUNG_CD, A.BUBJUNG_NM, A.HJD_CD, A.HJD_NM, A.ROAD_CD, A.EMD_SN, A.JIHA_YN, A.BUILDB_NO, A.BUILDS_NO, A.JIBUNB_NO, A.JIBUNS_NO, A.SIGUNGUB_NM, A.SIDO_NM || ' ' || A.SIGUNGU_NM || ' ' || A.BUBJUNG_NM || ' ' || JIBUNB_NO || DECODE(A.JIBUNS_NO,NULL,'','-' || A.JIBUNS_NO) AS JIBUN_AD FROM TM_POST_BUILD A JOIN TM_POST_CODE B ON A.ROAD_CD = TRIM(B.SIGUNGU_CD) || TRIM(B.ROAD_NO) AND A.EMD_SN = B.EMD_SN WHERE A.BUILDB_NO = #{BUILDB_NO} AND B.USE_YN = '0'
AND A.SIDO_NM = #{SIDO_NM}
AND A.BUBJUNGRI_NM LIKE TRIM(#{ROAD_NM}) || '%'
AND A.ROAD_NM LIKE TRIM(#{ROAD_NM}) || '%'
AND A.BUILDS_NO = #{BUILDS_NO}
UNION ALL
/* 지번 검색 */ SELECT A.GICHO_NO AS POST_NO, A.SIDO_NM || ' ' || A.SIGUNGU_NM || DECODE(B.EMD_GB, '0', ' ' || A.BUBJUNG_NM, '') || ' ' || A.ROAD_NM || DECODE(A.JIHA_YN, '0', '', '1', '지하', '2', '공중') || ' ' || A.BUILDB_NO || DECODE(A.BUILDS_NO, 0, ' ', '-' || A.BUILDS_NO || ' ' || A.SIGUNGUB_NM) || ' ' || CASE WHEN B.EMD_GB = '0' AND A.COMMB_YN = '0' THEN '' WHEN B.EMD_GB = '0' AND A.COMMB_YN = '1' THEN '(' || A.SIGUNGUB_NM || ')' WHEN B.EMD_GB = '1' AND A.COMMB_YN = '0' THEN '(' || A.BUBJUNG_NM || ')' WHEN B.EMD_GB = '1' AND A.COMMB_YN = '1' THEN '(' || A.BUBJUNG_NM || DECODE(A.SIGUNGUB_NM, NULL, '', ',' || A.SIGUNGUB_NM) || ')' END AS ROAD_AD, A.BUBJUNG_CD, A.BUBJUNG_NM, A.HJD_CD, A.HJD_NM, A.ROAD_CD, A.EMD_SN, A.JIHA_YN, A.BUILDB_NO, A.BUILDS_NO, A.JIBUNB_NO, A.JIBUNS_NO, A.SIGUNGUB_NM, A.SIDO_NM || ' ' || A.SIGUNGU_NM || ' ' || A.BUBJUNG_NM || ' ' || JIBUNB_NO || DECODE(A.JIBUNS_NO,NULL,'','-' || A.JIBUNS_NO) AS JIBUN_AD FROM TM_POST_BUILD A JOIN TM_POST_CODE B ON A.ROAD_CD = TRIM(B.SIGUNGU_CD) || TRIM(B.ROAD_NO) AND A.EMD_SN = B.EMD_SN
WHERE A.JIBUNB_NO = #{BUILDB_NO} AND B.USE_YN = '0'
AND A.SIDO_NM = #{SIDO_NM}
AND A.BUBJUNGRI_NM LIKE TRIM(#{ROAD_NM}) || '%'
AND A.BUBJUNG_NM LIKE TRIM(#{ROAD_NM}) || '%'
AND A.JIBUNS_NO = #{BUILDS_NO}
)
ORDER BY ROAD_AD, BUILDB_NO, BUILDS_NO


	    SELECT COUNT(*)
      FROM TR_CARNO_DETACH
     WHERE TOKEN = #{TOKEN}
       AND SERVICE_ID <> #{SERVICE_ID}

